"""Recreate both histories on a private Linux filesystem from official Ohm and a local Ruff clone."""
import argparse,hashlib,json,os,shutil,subprocess,sys
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--ruff',type=Path,required=True);p.add_argument('--sdk',type=Path,required=True);p.add_argument('--rustup-home',type=Path,required=True);p.add_argument('--proxies',type=Path,required=True);p.add_argument('--registry-home',type=Path,required=True);a=p.parse_args();root=a.root.resolve();assert not root.exists() and shutil.disk_usage(root.parent).free>85*1024**3;root.mkdir(mode=0o700);os.umask(0o077);src=Path(__file__).resolve().parent;env=dict(os.environ,FSTRING_ROOT=str(root),FSTRING_SDK=str(a.sdk.resolve()),FSTRING_RUSTUP=str(a.rustup_home.resolve()),FSTRING_PROXIES=str(a.proxies.resolve()));os.environ.update(env);sys.path.insert(0,str(src));from prime import H,OLD,PROXY,RELEASE_CARGO,SDK,sha
assert sha(SDK/'bin/cargo')==RELEASE_CARGO
for n in ('setup-home','setup-shared','setup-target','registry-base','states','receipts','objects','stale-control'):(root/n).mkdir()
for n in ('change.patch','caller.rs'):shutil.copyfile(src.parent/n,root/n)
run=lambda cmd,**kw:subprocess.run(cmd,check=True,**kw);run(['git','clone','--shared','--no-checkout',a.ruff.resolve(),root/'repo']);run(['git','-C',root/'repo','checkout','-q','--detach',H]);assert subprocess.check_output(['git','-C',root/'repo','rev-parse','HEAD^']).decode().strip()==OLD
e=dict(env,RUSTUP_HOME=str(a.rustup_home.resolve()),CARGO_HOME=str(root/'setup-home'),CARGO_TARGET_DIR=str(root/'setup-target'),CARGO_BUILD_BUILD_DIR=str(root/'setup-shared'),CARGO_NET_OFFLINE='true');run([PROXY/'cargo','+ohm','worktree','add','--target-dir',root/'unused-seed-target','--detach',root/'checkout',H],cwd=root/'repo',env=e)
source=a.registry_home.resolve();shutil.copytree(source/'registry',root/'registry-base/registry',symlinks=True);config=source/'config.toml';dst=root/'registry-base/config.toml';shutil.copyfile(config,dst) if config.is_file() else dst.write_text('');e.update(CARGO_HOME=str(root/'registry-base'),CARGO_NET_OFFLINE='false');run([PROXY/'cargo','+ohm','fetch','--locked'],cwd=root/'checkout',env=e);e['CARGO_NET_OFFLINE']='true';run([PROXY/'cargo','+ohm','metadata','--offline','--locked','--format-version','1'],cwd=root/'checkout',env=e,stdout=subprocess.DEVNULL);(root/'setup-complete.json').write_text(json.dumps({'head':H,'parent':OLD,'release_cargo':RELEASE_CARGO}))
for name in ('prime','cycle','stale_control_v2','analyze_v2','equal_width','slice_report'):
 print(name,flush=True);run([sys.executable,'-B',src/(name+'.py')],cwd=root,env=env)
